"""Questions du quiz de l'appli : (chapitre, question, [bonne réponse, autres…], explication)."""
QUIZ = [
    (1, "Quelle est la tessiture du soprano ?", ["Do4 – Sol5 (du Do central au Sol aigu)", "Sol3 – Ré5", "Do3 – Sol4", "Fa2 – Do4"],
     "Le soprano va du Do central au Sol aigu : une douzième, comme chaque voix."),
    (1, "Quelle est la tessiture de la basse ?", ["Fa2 – Do4 (du Fa grave au Do central)", "Do2 – Sol3", "Sol2 – Ré4", "Do3 – Sol4"],
     "La basse va du Fa grave au Do central."),
    (1, "Quel est l'écart maximum entre le soprano et l'alto ?", ["Une octave", "Une sixte", "Une dixième", "Une douzième"],
     "Les trois voix du haut restent soudées : une octave au plus entre soprano et alto, et entre alto et ténor."),
    (1, "Entre le ténor et la basse, l'écart peut aller jusqu'à…", ["la douzième", "l'octave", "la sixte", "la quinte"],
     "La basse peut s'éloigner : dans le grave, les notes ont besoin de place pour sonner."),
    (1, "Dans le quatuor à cordes, quel instrument joue la partie de ténor ?", ["L'alto", "Le 2e violon", "Le violoncelle", "La contrebasse"],
     "L'alto (l'instrument) joue la partie de ténor, en clé d'ut 3e ligne."),
    (1, "Sur la grande portée, quelles voix ont la hampe en haut ?", ["Soprano et ténor", "Soprano et alto", "Alto et basse", "Ténor et basse"],
     "Soprano et ténor : hampe en haut ; alto et basse : hampe en bas."),
    (2, "À l'état fondamental, quelle note double-t-on de préférence ?", ["La fondamentale", "La tierce", "La quinte", "La sensible"],
     "La fondamentale est la meilleure doublure. On peut aussi la tripler et supprimer la quinte."),
    (2, "Quelle note ne doit jamais être supprimée d'un accord parfait ?", ["La tierce", "La quinte", "La fondamentale doublée", "La note du soprano"],
     "Sans tierce, on ne sait plus si l'accord est majeur ou mineur : il sonne vide."),
    (2, "Quelle note ne double-t-on jamais ?", ["La sensible", "La tonique", "La dominante", "La sous-dominante"],
     "La sensible veut monter à la tonique : doublée, elle donnerait des octaves ou une mauvaise résolution."),
    (2, "En Do majeur, quels degrés portent un accord majeur ?", ["I, IV et V", "I, III et V", "II, IV et VI", "I, V et VII"],
     "C, F et G : les degrés principaux. II, III et VI sont mineurs, VII est diminué."),
    (3, "Pour enchaîner IV-V (aucune note commune), comment bougent les trois voix du haut ?", ["En mouvement contraire à la basse", "Dans le même sens que la basse", "Elles restent sur place", "Par saut de quarte"],
     "La basse monte de Fa à Sol, donc les voix du haut descendent vers la note la plus proche : pas de quintes ni d'octaves."),
    (3, "Une 5te directe entre soprano et basse est tolérée si…", ["le soprano avance par degré conjoint", "la basse avance par degré", "les deux voix sautent", "c'est en mineur"],
     "Interdite si le soprano saute, tolérée si le soprano fait un pas."),
    (3, "Deux voix passent d'une octave à une autre octave en mouvement contraire. C'est…", ["interdit aussi", "permis", "permis seulement entre alto et ténor", "conseillé à la cadence"],
     "Le mouvement contraire ne sauve rien : les deux voix chantent toujours la même note."),
    (3, "Qu'est-ce qu'un chevauchement ?", ["Une voix va plus loin que la note que sa voisine vient de quitter", "Deux voix chantent la même note", "Une voix passe sous la basse", "Un saut de plus d'une octave"],
     "Par exemple le soprano descend plus bas que la note précédente de l'alto : l'oreille croit que les voix s'échangent."),
    (3, "Dans un enchaînement, que font les notes communes aux deux accords ?", ["Elles restent à la même voix, sur place", "Elles changent de voix", "Elles montent d'une octave", "On les supprime"],
     "C'est la première règle de la méthode : garder les notes communes, puis le plus court chemin."),
    (6, "Que signifie le chiffrage 6 ?", ["La tierce de l'accord est à la basse", "La quinte est à la basse", "L'accord a une sixte ajoutée", "L'accord est sur le VI"],
     "Accord de sixte = 1er renversement : la tierce à la basse."),
    (6, "Dans le V6, quelle note ne double-t-on pas ?", ["La basse (la sensible)", "La fondamentale", "La quinte", "Aucune : tout est permis"],
     "La basse du V6 est la sensible : on ne la double jamais. Elle monte à la tonique."),
    (6, "Dans un accord de sixte majeur, on évite de doubler…", ["la basse (la tierce de l'accord)", "la fondamentale", "la quinte", "le soprano"],
     "Dans un accord de sixte majeur, la basse est la tierce majeure : on ne la double pas."),
    (7, "Quelle cadence s'arrête sur l'accord de V ?", ["La demi-cadence", "La cadence parfaite", "La cadence plagale", "La cadence rompue"],
     "La demi-cadence est une virgule : la phrase s'arrête sur V."),
    (7, "Quel enchaînement fait la cadence rompue ?", ["V – VI", "IV – I", "V – I", "II – V"],
     "On attend I après V, et c'est VI qui arrive : la surprise."),
    (7, "Dans la cadence rompue V-VI, quelle note du VI est doublée ?", ["La tierce", "La fondamentale", "La quinte", "Aucune"],
     "La sensible monte, les deux autres voix descendent : la tierce du VI est doublée. Elle est obligatoire ici."),
    (7, "La cadence plagale, c'est…", ["IV – I", "V – I", "II – V", "I – V"],
     "La conclusion douce de l'« Amen », souvent après une cadence parfaite."),
    (7, "Quel accord prépare le mieux une cadence parfaite ?", ["Le II6", "Le III", "Le VII", "Le VI6/4"],
     "La basse fait Fa-Sol-Do comme IV-V-I, et le Ré du II reste dans le V."),
    (8, "Dans un accord de quarte et sixte, on double…", ["la basse (la quinte de l'accord)", "la fondamentale", "la tierce", "rien : il est incomplet"],
     "Toujours doubler la basse du 6/4."),
    (8, "Où se place la quarte et sixte de cadence ?", ["Sur le temps fort, avant V", "Sur le temps faible, après V", "Au début de la phrase", "Entre deux accords de IV"],
     "I6/4 sur le temps fort, puis V : la 6te et la 4te descendent sur la 5te et la 3ce."),
    (8, "Combien d'usages de la quarte et sixte sont permis ?", ["Trois : de cadence, de passage, de broderie", "Un seul : de cadence", "Deux : de cadence et de passage", "Tous"],
     "En dehors de ces trois cas, un 6/4 est une faute."),
    (10, "En la mineur, que devient le 7e degré dans l'accord de V ?", ["Il est haussé : Sol♯", "Il reste Sol", "Il est baissé : Sol♭", "Il disparaît"],
     "Gamme mineure harmonique : le 7e degré est haussé, le V est majeur avec une vraie sensible."),
    (10, "Quel intervalle mélodique est interdit en mineur, entre le 6e et le 7e degré ?", ["La seconde augmentée (Fa – Sol♯)", "La tierce mineure", "La quarte juste", "Le demi-ton"],
     "Fa-Sol♯ est une seconde augmentée : jamais dans une voix."),
    (10, "En mineur, comment emploie-t-on l'accord de II (diminué) ?", ["Au 1er renversement : II6", "À l'état fondamental", "En 6/4", "On ne l'emploie jamais"],
     "Le II est diminué en mineur : on l'emploie en II6."),
    (10, "Comment chiffre-t-on le V à l'état fondamental en la mineur ?", ["Avec un ♯ (l'altération de la sensible)", "5", "6", "7"],
     "Le chiffrage indique l'altération de la tierce : ♯ pour Sol♯."),
    (13, "Une note de passage…", ["arrive et repart par degré, dans le même sens", "revient à la note de départ", "est préparée et liée", "arrive par saut sur le temps fort"],
     "Elle relie deux notes réelles, sur le temps faible."),
    (13, "Une broderie…", ["revient à la note de départ", "continue dans le même sens", "repart par saut", "est liée à la note précédente"],
     "Do-Si-Do : une petite broderie autour de la note."),
    (13, "Un retard est…", ["préparé (lié), sur le temps fort, et descend d'un degré", "non préparé, par saut, sur le temps fort", "sur le temps faible, déjà la note suivante", "une note de passage chromatique"],
     "C'est la même note, liée, qui appartenait à l'accord précédent. Comme la 4e espèce du contrepoint."),
    (13, "Quelle note étrangère est déjà la note de l'accord suivant ?", ["L'anticipation", "L'échappée", "L'appoggiature", "La broderie"],
     "L'anticipation chante la note de l'accord suivant un peu trop tôt."),
    (13, "Pour vérifier les doublures avec un retard, quelle note compte ?", ["La note de résolution (la note réelle)", "La note retardée", "Les deux", "Aucune"],
     "On vérifie l'harmonie sur les notes réelles : pour un retard, c'est la résolution."),
    (13, "Quelles notes étrangères sont accentuées (sur le temps fort) ?", ["Le retard et l'appoggiature", "Le passage et la broderie", "L'échappée et l'anticipation", "Toutes"],
     "Passage, broderie, échappée et anticipation se glissent sur le temps faible."),
    (15, "Pour harmoniser un choral, que fait-on en premier ?", ["Repérer les phrases et leurs cadences", "Écrire l'alto", "Ajouter les croches de passage", "Écrire le ténor"],
     "Chaque phrase finit par une cadence (les points d'orgue) : on part de là."),
    (15, "Dans un choral, combien d'accords par temps, en général ?", ["Un", "Deux", "Un par mesure", "Un par croche"],
     "Un accord par temps, sous chaque note réelle du soprano."),
]
